const languageButtons=document.querySelectorAll('[data-language]');
const translatable=document.querySelectorAll('[data-i18n]');
const placeholderTranslatable=document.querySelectorAll('[data-i18n-placeholder]');
const howTabs=document.querySelectorAll('[data-how]');
const howPanels=document.querySelectorAll('[data-how-panel]');
const heroVideo=document.querySelector('.hero-media video');
const videoToggle=document.querySelector('.video-toggle');
const filmModal=document.querySelector('.film-modal');
const filmVideo=filmModal.querySelector('video');
const toast=document.querySelector('#toast');
const cursorAura=document.querySelector('.cursor-aura');
const energyOptions=[...document.querySelectorAll('[data-energy-option]')];
const energyPhonePanels=[...document.querySelectorAll('[data-energy-phone]')];
heroVideo.loop=true;
filmVideo.loop=true;
let currentLanguage=localStorage.getItem('pixopet-language')||'en';
let toastTimer;

function applyLanguage(language){
  const copy=translations[language]||translations.en;
  currentLanguage=language;
  document.documentElement.lang=language==='zh'?'zh-CN':'en';
  document.title=copy.title;
  document.querySelector('meta[name="description"]').setAttribute('content',copy.description);
  translatable.forEach(element=>{const value=copy[element.dataset.i18n];if(typeof value==='string')element.innerHTML=value});
  placeholderTranslatable.forEach(element=>{const value=copy[element.dataset.i18nPlaceholder];if(typeof value==='string')element.setAttribute('placeholder',value)});
  languageButtons.forEach(button=>{const active=button.dataset.language===language;button.classList.toggle('is-active',active);button.setAttribute('aria-pressed',String(active))});
  energyOptions.forEach(button=>{const label=copy[button.dataset.energyLabel];if(label)button.setAttribute('aria-label',label)});
  document.querySelectorAll('[data-download],[data-app-store-link]').forEach(button=>button.setAttribute('aria-label',copy.downloadIphone||copy.download));
  energyPhonePanels.forEach(panel=>{const english=language==='en';const source=english?panel.dataset.srcEn:panel.dataset.srcZh;const alt=english?panel.dataset.altEn:panel.dataset.altZh;if(source&&panel.getAttribute('src')!==source)panel.setAttribute('src',source);if(alt)panel.setAttribute('alt',alt)});
  localStorage.setItem('pixopet-language',language);
}

function showToast(message){toast.textContent=message;toast.classList.add('is-visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('is-visible'),3200)}
function openDownload(){document.querySelector('#download')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'})}
function setHowStep(step){howTabs.forEach(tab=>{const active=tab.dataset.how===step;tab.classList.toggle('is-active',active);tab.setAttribute('aria-selected',String(active))});howPanels.forEach(panel=>panel.classList.toggle('is-active',panel.dataset.howPanel===step))}
function setEnergyState(state,{focus=false}={}){
  energyOptions.forEach(button=>{const active=button.dataset.energyOption===state;button.classList.toggle('is-active',active);button.setAttribute('aria-checked',String(active));button.tabIndex=active?0:-1;if(active&&focus)button.focus({preventScroll:true})});
  energyPhonePanels.forEach(panel=>{const active=panel.dataset.energyPhone===state;panel.classList.toggle('is-active',active);panel.setAttribute('aria-hidden',String(!active))});
}

const revealObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-in-view');revealObserver.unobserve(entry.target)}}),{threshold:.12});
document.querySelectorAll('[data-reveal]').forEach(element=>revealObserver.observe(element));

let motionFrame;
function updateParallax(){cancelAnimationFrame(motionFrame);motionFrame=requestAnimationFrame(()=>{document.querySelectorAll('[data-parallax]').forEach(element=>{const rect=element.getBoundingClientRect();const progress=innerHeight*.5-(rect.top+rect.height*.5);const speed=Number(element.dataset.parallax)||0;element.style.setProperty('--parallax-y',`${Math.max(-80,Math.min(80,progress*speed))}px`)})})}

function initCursorAura(){
  if(!cursorAura||!matchMedia('(pointer: fine)').matches||matchMedia('(prefers-reduced-motion: reduce)').matches)return;
  let targetX=innerWidth*.5,targetY=innerHeight*.38,currentX=targetX,currentY=targetY,auraFrame;
  const render=()=>{currentX+=(targetX-currentX)*.115;currentY+=(targetY-currentY)*.115;cursorAura.style.transform=`translate3d(${currentX}px,${currentY}px,0)`;if(Math.abs(targetX-currentX)>.2||Math.abs(targetY-currentY)>.2)auraFrame=requestAnimationFrame(render);else auraFrame=0};
  let pointerX=targetX,pointerY=targetY;
  const updateAuraArea=()=>{const underPointer=document.elementFromPoint(pointerX,pointerY);const area=underPointer&&underPointer.closest('.hero,.download-section');cursorAura.classList.toggle('is-active',Boolean(area));if(!area)return;const changedArea=cursorAura.parentElement!==area;if(changedArea)area.prepend(cursorAura);const rect=area.getBoundingClientRect();targetX=pointerX-rect.left;targetY=pointerY-rect.top;if(changedArea){currentX=targetX;currentY=targetY}if(!auraFrame)auraFrame=requestAnimationFrame(render)};
  const move=event=>{pointerX=event.clientX;pointerY=event.clientY;updateAuraArea()};
  addEventListener('pointermove',move,{passive:true});
  addEventListener('scroll',updateAuraArea,{passive:true});
  document.documentElement.addEventListener('pointerleave',()=>cursorAura.classList.remove('is-active'));
  addEventListener('blur',()=>cursorAura.classList.remove('is-active'));
}

function initPointerPetsPilot(){
  const stage=document.querySelector('[data-pointer-pets]');
  const atlas=document.querySelector('[data-pointer-pets-atlas]');
  const hero=document.querySelector('.hero');
  if(!stage||!atlas||!hero||!matchMedia('(pointer: fine)').matches||matchMedia('(prefers-reduced-motion: reduce)').matches)return;
  const canvas=document.createElement('canvas');
  canvas.className='pointer-pets-canvas';
  stage.append(canvas);
  const context=canvas.getContext('2d',{alpha:true});
  const atlasImage=new Image();
  atlasImage.src='assets/pointer-pets-25way.webp';
  let imageReady=false;
  let targetX=0,targetY=0,currentX=0,currentY=0,currentState='r2c2',poseColumn=2,poseRow=2,animationFrame=0,isVisible=true;
  const syncCanvasSize=()=>{
    const rect=stage.getBoundingClientRect();
    const pixelRatio=Math.min(devicePixelRatio||1,1.7);
    const width=Math.max(1,Math.round(rect.width*pixelRatio));
    const height=Math.max(1,Math.round(rect.height*pixelRatio));
    if(canvas.width!==width||canvas.height!==height){canvas.width=width;canvas.height=height;context.imageSmoothingEnabled=true;context.imageSmoothingQuality='high'}
  };
  const drawFrame=(column,row,opacity)=>{
    if(opacity<=.001)return;
    const cellWidth=atlasImage.naturalWidth/5,cellHeight=atlasImage.naturalHeight/5;
    context.globalAlpha=opacity;
    context.drawImage(atlasImage,column*cellWidth,row*cellHeight,cellWidth,cellHeight,0,0,canvas.width,canvas.height);
  };
  const drawPose=(column,row)=>{
    if(!imageReady)return;
    context.clearRect(0,0,canvas.width,canvas.height);
    drawFrame(column,row,1);
    context.globalAlpha=1;
    context.globalCompositeOperation='source-over';
  };
  const selectPose=(position,current)=>{
    // A small dead zone prevents rapid frame chatter when the pointer sits on
    // a pose boundary. Frames stay sharp instead of cross-fading two faces.
    while(current<4&&position>current+.62)current+=1;
    while(current>0&&position<current-.62)current-=1;
    return current;
  };
  const render=()=>{
    currentX+=(targetX-currentX)*.12;
    currentY+=(targetY-currentY)*.12;
    poseColumn=selectPose(Math.max(0,Math.min(4,(currentX+1)*2)),poseColumn);
    poseRow=selectPose(Math.max(0,Math.min(4,(currentY+1)*2)),poseRow);
    const nextState=`r${poseRow}c${poseColumn}`;
    if(nextState!==currentState){currentState=nextState;stage.dataset.pointerState=currentState}
    drawPose(poseColumn,poseRow);
    const isMoving=Math.abs(targetX-currentX)>.002||Math.abs(targetY-currentY)>.002;
    if(isVisible&&isMoving)animationFrame=requestAnimationFrame(render);else animationFrame=0;
  };
  const requestRender=()=>{if(isVisible&&!animationFrame)animationFrame=requestAnimationFrame(render)};
  const move=event=>{
    if(!isVisible)return;
    const rect=stage.getBoundingClientRect();
    const centerX=rect.left+rect.width*.5;
    const centerY=rect.top+rect.height*.5;
    const deltaX=event.clientX-centerX;
    const deltaY=event.clientY-centerY;
    const horizontalRange=deltaX<0?centerX:innerWidth-centerX;
    const verticalRange=deltaY<0?centerY:innerHeight-centerY;
    targetX=Math.max(-1,Math.min(1,deltaX/Math.max(1,horizontalRange)));
    targetY=Math.max(-1,Math.min(1,deltaY/Math.max(1,verticalRange)));
    requestRender();
  };
  addEventListener('pointermove',move,{passive:true});
  addEventListener('pointerdown',move,{passive:true});
  document.documentElement.addEventListener('pointerleave',()=>{targetX=0;targetY=0;requestRender()});
  document.addEventListener('visibilitychange',()=>{if(document.hidden){targetX=0;targetY=0;requestRender()}});
  new IntersectionObserver(entries=>{isVisible=Boolean(entries[0]?.isIntersecting);if(isVisible)requestRender()},{rootMargin:'120px'}).observe(stage);
  new ResizeObserver(()=>{if(imageReady){syncCanvasSize();drawPose(poseColumn,poseRow)}}).observe(stage);
  atlasImage.decode?.().then(()=>{imageReady=true;syncCanvasSize();drawPose(2,2);canvas.classList.add('is-ready');atlas.classList.add('is-hidden');stage.classList.add('is-ready')}).catch(()=>{stage.dataset.pointerFallback='static';canvas.remove()});
}

languageButtons.forEach(button=>button.addEventListener('click',()=>applyLanguage(button.dataset.language)));
howTabs.forEach(tab=>tab.addEventListener('click',()=>setHowStep(tab.dataset.how)));
energyOptions.forEach((button,index)=>{
  button.addEventListener('click',()=>setEnergyState(button.dataset.energyOption));
  button.addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(event.key))return;event.preventDefault();const direction=event.key==='ArrowLeft'||event.key==='ArrowUp'?-1:1;const next=(index+direction+energyOptions.length)%energyOptions.length;setEnergyState(energyOptions[next].dataset.energyOption,{focus:true})});
});
document.querySelectorAll('[data-download]').forEach(button=>button.addEventListener('click',openDownload));
document.querySelectorAll('video').forEach(video=>video.addEventListener('error',()=>{video.classList.add('is-failed');video.parentElement?.classList.add('has-video-error');showToast(translations[currentLanguage].videoError||'Video could not be loaded')}));
document.querySelectorAll('[data-open-film]').forEach(button=>button.addEventListener('click',()=>{filmModal.classList.add('is-open');filmModal.setAttribute('aria-hidden','false');filmVideo.play().catch(()=>{})}));
document.querySelector('.film-close').addEventListener('click',closeFilm);
filmModal.addEventListener('click',event=>{if(event.target===filmModal)closeFilm()});
document.addEventListener('keydown',event=>{if(event.key==='Escape')closeFilm()});
function closeFilm(){filmModal.classList.remove('is-open');filmModal.setAttribute('aria-hidden','true');filmVideo.pause()}
videoToggle.addEventListener('click',()=>{if(heroVideo.paused){heroVideo.play();videoToggle.textContent='Ⅱ';videoToggle.setAttribute('aria-label','Pause background video')}else{heroVideo.pause();videoToggle.textContent='▶';videoToggle.setAttribute('aria-label','Play background video')}});
addEventListener('scroll',updateParallax,{passive:true});
applyLanguage(currentLanguage);setHowStep('hatch');setEnergyState('move');updateParallax();initCursorAura();

// Tall chapters land at their introduction. Native snap lets readers scroll inside them.
const readableChapters = document.querySelectorAll('.voices-section,.faq-section');
const siteHeader = document.querySelector('.site-header');
function sizeReadingChapters() {
  const usableHeight = document.documentElement.clientHeight - siteHeader.offsetHeight;
  for (const chapter of readableChapters) {
    chapter.classList.toggle('is-tall-chapter', chapter.offsetHeight > usableHeight + 1);
  }
}
const chapterResize = new ResizeObserver(sizeReadingChapters);
for (const chapter of readableChapters) chapterResize.observe(chapter);
chapterResize.observe(siteHeader);
window.addEventListener('resize', sizeReadingChapters);
sizeReadingChapters();

// The download section and the localized footer share the final viewport.
const siteFooter = document.querySelector('body > footer');
function measureFooter() {
  document.documentElement.style.setProperty('--footer-height', siteFooter.getBoundingClientRect().height + 'px');
}
new ResizeObserver(measureFooter).observe(siteFooter);
measureFooter();
